mapper.update:
UPDATE im_conversation_member
SET last_read_message_id = #{messageId},
    last_read_at = #{at},
    updated_at = #{at},
    version = version + 1
WHERE conversation_id = #{conversationId}
AND principal_type = #{principalType}
AND principal_id = #{principalId}
AND deleted = 0
AND (last_read_message_id IS NULL OR last_read_message_id < #{messageId})

UPDATE im_message
SET status = #{nextStatus},
    content = NULL,
    revoked_at = #{revokedAt},
    version = version + 1
WHERE id = #{messageId}
AND sender_principal_type = #{principalType}
AND sender_principal_id = #{principalId}
AND status = #{currentStatus}
AND deleted = 0
